/* ---------------------------------------------------------------- */
/* Three.js particle / energy-line background                       */
/* ---------------------------------------------------------------- */
function ParticleBackground() {
  const mountRef = useRef(null);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    const width = mount.clientWidth;
    const height = mount.clientHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 200);
    camera.position.z = 40;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
    mount.appendChild(renderer.domElement);

    /* ---- particle field ---- */
    const PARTICLE_COUNT = window.innerWidth < 768 ? 1800 : 6000;
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const basePositions = new Float32Array(PARTICLE_COUNT * 3);
    const velocities = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);

    const baseColor = new THREE.Color(0x001f3f);
    const limeColor = new THREE.Color(0xccff00);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const x = (Math.random() - 0.5) * 80;
      const y = (Math.random() - 0.5) * 55;
      const z = (Math.random() - 0.5) * 60;
      positions[i * 3] = x;
      positions[i * 3 + 1] = y;
      positions[i * 3 + 2] = z;
      basePositions[i * 3] = x;
      basePositions[i * 3 + 1] = y;
      basePositions[i * 3 + 2] = z;
      colors[i * 3] = baseColor.r;
      colors[i * 3 + 1] = baseColor.g;
      colors[i * 3 + 2] = baseColor.b;
    }

    const particleGeo = new THREE.BufferGeometry();
    particleGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    particleGeo.setAttribute("color", new THREE.BufferAttribute(colors, 3));

    const particleMat = new THREE.PointsMaterial({
      size: 0.5,
      transparent: true,
      opacity: 0.6,
      vertexColors: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });

    const points = new THREE.Points(particleGeo, particleMat);
    scene.add(points);

    /* ---- energy lines moving forward in Z ---- */
    const LINE_COUNT = window.innerWidth < 768 ? 80 : 200;
    const lineSegLen = 6;
    const linePositions = new Float32Array(LINE_COUNT * 2 * 3);
    const lineSpeeds = new Float32Array(LINE_COUNT);

    function resetLine(i) {
      const x = (Math.random() - 0.5) * 70;
      const y = (Math.random() - 0.5) * 45;
      const z = -90 - Math.random() * 40;
      linePositions[i * 6] = x;
      linePositions[i * 6 + 1] = y;
      linePositions[i * 6 + 2] = z;
      linePositions[i * 6 + 3] = x;
      linePositions[i * 6 + 4] = y;
      linePositions[i * 6 + 5] = z - lineSegLen;
      lineSpeeds[i] = 0.3 + Math.random() * 0.5;
    }
    for (let i = 0; i < LINE_COUNT; i++) resetLine(i);

    const lineGeo = new THREE.BufferGeometry();
    lineGeo.setAttribute("position", new THREE.BufferAttribute(linePositions, 3));
    const lineMat = new THREE.LineBasicMaterial({
      color: 0x88aaff,
      transparent: true,
      opacity: 0.2,
    });
    const lines = new THREE.LineSegments(lineGeo, lineMat);
    scene.add(lines);

    /* ---- mouse interaction ---- */
    const mouseNDC = new THREE.Vector2(-10, -10);
    const raycaster = new THREE.Raycaster();
    const interactPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
    const mouseWorld = new THREE.Vector3(9999, 9999, 0);

    function onPointerMove(e) {
      const rect = mount.getBoundingClientRect();
      mouseNDC.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouseNDC.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    }
    function onPointerLeave() {
      mouseNDC.set(-10, -10);
    }
    mount.addEventListener("mousemove", onPointerMove);
    mount.addEventListener("mouseleave", onPointerLeave);

    const REPULSE_DIST = 20;
    const FORCE_MULT = 0.04;
    const MAX_COLOR_MIX = 0.4;
    const SPRING_K = 0.02;
    const DAMPING = 0.9;

    let rafId;
    const tmpColor = new THREE.Color();

    function animate() {
      raycaster.setFromCamera(mouseNDC, camera);
      raycaster.ray.intersectPlane(interactPlane, mouseWorld);
      if (!mouseWorld) mouseWorld.set(9999, 9999, 0);

      const posAttr = particleGeo.attributes.position.array;
      const colAttr = particleGeo.attributes.color.array;

      for (let i = 0; i < PARTICLE_COUNT; i++) {
        const ix = i * 3, iy = i * 3 + 1, iz = i * 3 + 2;
        const dx = posAttr[ix] - mouseWorld.x;
        const dy = posAttr[iy] - mouseWorld.y;
        const dz = posAttr[iz] - mouseWorld.z;
        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz) || 0.0001;

        let mix = 0;
        if (dist < REPULSE_DIST) {
          const force = ((REPULSE_DIST - dist) / REPULSE_DIST) * FORCE_MULT;
          velocities[ix] += (dx / dist) * force;
          velocities[iy] += (dy / dist) * force;
          velocities[iz] += (dz / dist) * force;
          mix = (1 - dist / REPULSE_DIST) * MAX_COLOR_MIX;
        }

        velocities[ix] += (basePositions[ix] - posAttr[ix]) * SPRING_K;
        velocities[iy] += (basePositions[iy] - posAttr[iy]) * SPRING_K;
        velocities[iz] += (basePositions[iz] - posAttr[iz]) * SPRING_K;

        velocities[ix] *= DAMPING;
        velocities[iy] *= DAMPING;
        velocities[iz] *= DAMPING;

        posAttr[ix] += velocities[ix];
        posAttr[iy] += velocities[iy];
        posAttr[iz] += velocities[iz];

        tmpColor.copy(baseColor).lerp(limeColor, mix);
        colAttr[ix] = tmpColor.r;
        colAttr[iy] = tmpColor.g;
        colAttr[iz] = tmpColor.b;
      }
      particleGeo.attributes.position.needsUpdate = true;
      particleGeo.attributes.color.needsUpdate = true;

      const lPos = lineGeo.attributes.position.array;
      for (let i = 0; i < LINE_COUNT; i++) {
        lPos[i * 6 + 2] += lineSpeeds[i];
        lPos[i * 6 + 5] += lineSpeeds[i];
        if (lPos[i * 6 + 2] > camera.position.z) {
          resetLine(i);
        }
      }
      lineGeo.attributes.position.needsUpdate = true;

      renderer.render(scene, camera);
      rafId = requestAnimationFrame(animate);
    }
    animate();

    function onResize() {
      const w = mount.clientWidth, h = mount.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    }
    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(rafId);
      window.removeEventListener("resize", onResize);
      mount.removeEventListener("mousemove", onPointerMove);
      mount.removeEventListener("mouseleave", onPointerLeave);
      particleGeo.dispose();
      particleMat.dispose();
      lineGeo.dispose();
      lineMat.dispose();
      renderer.dispose();
      if (renderer.domElement.parentNode === mount) {
        mount.removeChild(renderer.domElement);
      }
    };
  }, []);

  return (
    <div
      ref={mountRef}
      className="absolute inset-0 z-0"
      style={{ pointerEvents: "auto", filter: "brightness(1.15) saturate(1.15)" }}
    />
  );
}

