/* ---------------------------------------------------------------- */
/* Scramble-text word rotator                                        */
/* ---------------------------------------------------------------- */
const SCRAMBLE_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

function ScrambleRotator({ words, style }) {
  const [display, setDisplay] = useState(words[0]);
  const indexRef = useRef(0);
  const frameRef = useRef(null);

  const scrambleTo = useCallback((target) => {
    let iteration = 0;
    const totalIterations = target.length * 3;
    clearInterval(frameRef.current);
    frameRef.current = setInterval(() => {
      setDisplay(
        target
          .split("")
          .map((ch, i) => {
            if (i < iteration / 3) return target[i];
            return SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)];
          })
          .join("")
      );
      iteration += 1;
      if (iteration > totalIterations) {
        clearInterval(frameRef.current);
        setDisplay(target);
      }
    }, 30);
  }, []);

  useEffect(() => {
    const id = setInterval(() => {
      indexRef.current = (indexRef.current + 1) % words.length;
      scrambleTo(words[indexRef.current]);
    }, 4000);
    return () => {
      clearInterval(id);
      clearInterval(frameRef.current);
    };
  }, [words, scrambleTo]);

  return (
    <div
      style={{
        fontFamily: "var(--font-display)",
        lineHeight: 0.95,
        color: COLORS.lime,
        ...style,
      }}
    >
      {display}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Typewriter bio (loops every 7s)                                   */
/* ---------------------------------------------------------------- */
function TypewriterBio({ text }) {
  const [loopKey, setLoopKey] = useState(0);

  useEffect(() => {
    const id = setInterval(() => setLoopKey((k) => k + 1), 7000);
    return () => clearInterval(id);
  }, []);

  return (
    <p
      key={loopKey}
      className="max-w-xl text-sm md:text-base px-2"
      style={{ color: COLORS.textDim }}
    >
      {text.split("").map((ch, i) => (
        <motion.span
          key={i}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: i * 0.02, duration: 0.05 }}
        >
          {ch}
        </motion.span>
      ))}
    </p>
  );
}

