function ProjectsView() {
  const [projects, setProjects] = useState(LEGACY_PROJECTS);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchPublishedProjects()
      .then(setProjects)
      .catch((loadError) => setError(loadError.message || "Projects could not be loaded."))
      .finally(() => setLoading(false));
  }, []);

  return (
    <article className="flex flex-col gap-8">
      <div>
        <p
          className="mb-3 text-xs tracking-widest"
          style={{ fontFamily: "var(--font-mono)", color: COLORS.lime }}
        >
          SELECTED WORK / 2026
        </p>
        <h2
          className="uppercase leading-none"
          style={{ fontFamily: "var(--font-display)", fontSize: "clamp(42px, 10vw, 76px)" }}
        >
          Built to<br />
          connect.
        </h2>
        <p className="mt-5 leading-relaxed" style={{ color: "rgba(255,255,255,0.7)" }}>
          Explore selected websites, apps, and posters. Each project opens in a new
          tab so clients can view your work without losing their place here.
        </p>
      </div>

      <div className="flex flex-col">
        {loading && <p className="border-t py-6 text-sm opacity-60">Loading projects...</p>}
        {error && <p className="border-t py-6 text-sm" style={{ color: COLORS.lime }}>{error}</p>}
        {!loading && !error && projects.filter((project) => project.featured).length > 0 && (
          <p className="border-t py-6 text-xs tracking-widest" style={{ color: COLORS.lime, fontFamily: "var(--font-mono)" }}>
            FEATURED PROJECTS
          </p>
        )}
        {projects.map((project) => (
          <article
            key={project.id || project.number}
            className="border-t py-6"
            style={{ borderColor: "rgba(255,255,255,0.16)" }}
          >
            {project.image_url && <img src={project.image_url} alt="" className="mb-5 aspect-[16/8] w-full object-cover" />}
            <div className="flex items-start justify-between gap-4">
              <p className="text-xs tracking-widest opacity-50" style={{ fontFamily: "var(--font-mono)" }}>
                {project.number} / {project.category}
              </p>
              {project.project_url ? (
                <a
                  href={`/project/${project.id}`}
                  target="_blank"
                  rel="noreferrer"
                  aria-label={`View ${project.title}`}
                  className="flex shrink-0 items-center gap-1 text-xs tracking-widest transition-opacity hover:opacity-70"
                  style={{ color: COLORS.lime, fontFamily: "var(--font-mono)" }}
                >
                  VIEW LIVE <ArrowUpRight size={14} />
                </a>
              ) : (
                <span className="text-xs tracking-widest opacity-40" style={{ fontFamily: "var(--font-mono)" }}>
                  LINK PENDING
                </span>
              )}
            </div>
            <h3 className="mt-4 text-2xl leading-tight" style={{ fontFamily: "var(--font-display)" }}>
              {project.title}
            </h3>
            <p className="mt-3 leading-relaxed" style={{ color: "rgba(255,255,255,0.7)" }}>
              {project.short_description}
            </p>
            <a
              href={`/project/${project.id}`}
              className="mt-5 inline-flex w-fit items-center gap-2 rounded-full px-4 py-2 text-xs tracking-widest transition-opacity hover:opacity-80"
              style={{ background: COLORS.lime, color: "#000", fontFamily: "var(--font-mono)" }}
            >
              VIEW PROJECT <ArrowUpRight size={14} />
            </a>
            {project.project_url && (
              <a
                href={project.project_url}
                target="_blank"
                rel="noreferrer"
                className="ml-3 mt-5 inline-flex w-fit items-center gap-2 text-xs tracking-widest transition-opacity hover:opacity-70"
                style={{ color: COLORS.lime, fontFamily: "var(--font-mono)" }}
              >
                LIVE LINK <ArrowUpRight size={14} />
              </a>
            )}
          </article>
        ))}
      </div>
    </article>
  );
}

