function InfoDrawer({ open, view, setView, onClose }) {
  return (
    <AnimatePresence>
      {open && (
        <>
          <motion.div
            className="fixed inset-0 z-40"
            style={{ background: "rgba(0,0,0,0.55)" }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <motion.div
            className="fixed top-0 right-0 h-full z-50 flex flex-col w-full"
            style={{
              background: COLORS.drawer,
              maxWidth: 560,
              borderLeft: "1px solid rgba(255,255,255,0.05)",
            }}
            initial={{ x: "100%" }}
            animate={{ x: 0 }}
            exit={{ x: "100%" }}
            transition={{ type: "spring", damping: 32, stiffness: 300 }}
          >
            <div
              className="sticky top-0 flex items-center justify-between px-6 py-5 z-10"
              style={{ background: "rgba(51,51,51,0.9)", backdropFilter: "blur(8px)" }}
            >
              {view !== "menu" ? (
                <button
                  onClick={() => setView("menu")}
                  className="flex items-center gap-2 text-xs tracking-widest opacity-70 hover:opacity-100"
                  style={{ fontFamily: "var(--font-mono)" }}
                >
                  <ArrowLeft size={16} /> MENU
                </button>
              ) : (
                <span
                  className="text-xs tracking-widest opacity-60"
                  style={{ fontFamily: "var(--font-mono)" }}
                >
                  MENU
                </span>
              )}
              <button onClick={onClose} className="p-2" aria-label="Close menu">
                <X size={20} />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto px-6 py-8">
              {view === "menu" ? (
                <MenuList
                  onSelect={setView}
                />
              ) : view === "projects" ? (
                <ProjectsView />
              ) : view === "about" ? (
                <AboutView />
              ) : view === "blog" ? (
                <BlogView />
              ) : view === "archive" ? (
                <ArchiveView />
              ) : view === "process" ? (
                <ProcessView />
              ) : view === "labs" ? (
                <LabsView />
              ) : (
                <ContactForm />
              )}
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

