/* App                                                                */
/* ---------------------------------------------------------------- */
export default function App() {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [drawerView, setDrawerView] = useState("menu");

  return (
    <div
      className="clevis-root relative flex flex-col min-h-screen overflow-hidden"
      style={{ background: COLORS.bg, color: COLORS.white }}
    >
      <GlobalStyles />
      <ParticleBackground />
      <Header
        onOpenDrawer={() => {
          setDrawerView("menu");
          setDrawerOpen(true);
        }}
        onOpenView={(view) => {
          setDrawerView(view);
          setDrawerOpen(true);
        }}
      />
      <main className="relative flex-1 flex flex-col overflow-hidden">
        <HeroContent />
        <HeroImage />
      </main>
      <FooterMarquee />
      <InfoDrawer
        open={drawerOpen}
        view={drawerView}
        setView={setDrawerView}
        onClose={() => setDrawerOpen(false)}
      />
    </div>
  );
}
